export interface PibPressReleaseNotice {
  prid: string;
  url: string;
  title: string;
  authority: string;
  collaborator?: string;
  eventDate: string;
  description: string;
  sports: string[];
  delegations?: string[];
  infrastructure?: string;
}

export interface Venue {
  id: string;
  name: string;
  area: string;
  city: string;
  distanceKm: number;
  rating: number;
  reviews: number;
  sports: string[];
  pricePerHour: number;
  featured?: boolean;
  bookable?: boolean;
  image: string;
  pibPressRelease?: PibPressReleaseNotice;
  officialUrl?: string;
  trialId?: string;
  trialTitle?: string;
  association?: string;
}

export interface CoachingProgram {
  id: string;
  title: string;
  coach: string;
  sport: string;
  city: string;
  area: string;
  level: "Beginner" | "Intermediate" | "Advanced" | "All Levels";
  pricePerMonth: number;
  rating: number;
  image: string;
  entityType?: "coach" | "academy";
  academyName?: string;
  accreditation?: string;
  facilities?: string[];
  format?: "Academy Batch" | "1-on-1 Private" | "Weekend Camp" | "High-Performance Combine";
  ageGroup?: "U-12 Grassroots" | "U-16 Youth" | "U-19 Junior" | "Senior / Open" | "All Ages";
  certified?: boolean;
  freeTrial?: boolean;
  sessionsPerWeek?: number;
  reviewsCount?: number;
  experienceYears?: number;
  highlights?: string[];
}

export interface CoachProfile {
  id: string;
  name: string;
  sport: string;
  city: string;
  area: string;
  yearsExperience: number;
  rating: number;
  reviewCount: number;
  specialties: string[];
  availability: string;
  image: string;
}

export interface SportEvent {
  id: string;
  title: string;
  sport: string;
  city: string;
  venue: string;
  date: string;
  time: string;
  entryFee: number;
  spotsLeft: number;
  format: string;
  image: string;
  area?: string;
  prizePool?: string;
  totalSpots?: number;
  category?:
    "Weekend Cup" | "Corporate League" | "Championship" | "Youth & Grassroots" | "Community Open";
  scope?: "Local" | "National" | "State";
  status?: "Upcoming" | "Registration Open" | "Filling Fast" | "Sold Out";
  teamFormat?:
    "Singles" | "Doubles" | "Small Teams (5-7)" | "Full Squad (11v11)" | "Open Individual";
  skillLevel?: "Open / All Levels" | "Amateur / Intermediate" | "Competitive / Semi-Pro";
  organizer?: {
    name: string;
    verified: boolean;
    contact?: string;
  };
  perks?: string[];
  rulesHighlights?: string[];
  schedulePreview?: { round: string; matchTime: string }[];
  registrationDeadline?: string;
}

export interface Game {
  id: string;
  sport: string;
  city: string;
  venue: string;
  date: string;
  time: string;
  skillLevel: "Beginner" | "Intermediate" | "Advanced";
  host: string;
  joined: number;
  capacity: number;
  costPerPlayer: number;
}

export interface Membership {
  id: string;
  name: string;
  venue: string;
  city: string;
  sport: string;
  durationMonths: number;
  price: number;
  perks: string[];
  popular?: boolean;
}

